// initial nodes and edges
function constructor() {
  const nodes = [];
  const edges = [];
  for (let index = 0; index < userList.value.length; index += 1) {
    const element = userList.value[index];
    if ((element as any).Instrument !== 'Robot1' && index !== userList.value.length) {
      nodes.push({
        id: String(index),
        position: { x: 0, y: 0 },
        type: 'process',
        data: element,
        origin: index,
      });
      edges.push({
        id: `e${index}-${index + 1}`,
        source: String(index),
        target: String(index + 1),
        type: 'animation',
        animated: true,
      });
    }
    if ((element as any).Instrument === 'Robot1'
      && (userList.value[index + 1] as any).Instrument === 'Robot1') {
      edges.push({
        id: `e${index - 1}-${index + 2}`,
        source: String(index - 1),
        target: String(index + 2),
        type: 'animation',
        animated: true,
        data: element,
        origin: index,
      });
    }
    if ((element as any).Instrument === 'Robot1'
      && (userList.value[index - 1] as any).Instrument === 'Robot1') {
      edges.push({
        id: `e${index - 2}-${index + 1}`,
        source: String(index - 2),
        target: String(index + 1),
        type: 'animation',
        animated: true,
        data: element,
        origin: index,
      });
    }
  }
  localStorage.setItem('nodes', JSON.stringify(nodes));
  localStorage.setItem('edges', JSON.stringify(edges));
}

